/** Only read-only data needed by the desktop renderer. */
export type GilbertPreviewResult = {
  id: string;
  name: string;
  kind: 'image' | 'text';
  page: number;
  pageCount: number;
  /** Data URLs are generated by the local previewer (never from raw HTML or SVG documents). */
  dataUrl?: string;
  /** Text is rendered by React as text, not executable markup. */
  text?: string;
};
